import React, { useEffect, useState } from "react";
import axios from "axios";

export default function AdminPayments() {
  const [payments, setPayments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [search, setSearch] = useState("");

  const fetchPayments = async () => {
    try {
      const token = localStorage.getItem("admintoken");

      const response = await axios.get("http://localhost:4000/admin/payments", {
        headers: { Authorization: `Bearer ${token}` },
      });

      setPayments(response.data);
      setLoading(false);
    } catch (err) {
      console.error("❌ Payments Fetch Error:", err);
      setError("Failed to fetch payments. Check Admin Token!");
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPayments();
  }, []);

  const filteredPayments = payments.filter(
    (item) =>
      item.customer_name?.toLowerCase().includes(search.toLowerCase()) ||
      item.payment_id?.toLowerCase().includes(search.toLowerCase()) ||
      String(item.order_id).includes(search)
  );

  return (
    <div style={containerStyle}>
      <h2 style={titleStyle}>💳 Payment Records</h2>

      <input
        type="text"
        placeholder="Search by Order ID, Customer, Payment ID"
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        style={searchStyle}
      />

      {loading && <p style={loadingStyle}>Fetching payments...</p>}
      {error && <p style={errorStyle}>{error}</p>}

      {!loading && !error && filteredPayments.length === 0 && (
        <p style={noDataStyle}>No payment records found.</p>
      )}

      {!loading && !error && filteredPayments.length > 0 && (
        <table style={tableStyle}>
          <thead>
            <tr>
              <th style={thStyle}>Order ID</th>
              <th style={thStyle}>Customer Name</th>
              <th style={thStyle}>Email</th>
              <th style={thStyle}>Amount</th>
              <th style={thStyle}>Payment ID</th>
              <th style={thStyle}>Status</th>
              <th style={thStyle}>Date</th>
            </tr>
          </thead>

          <tbody>
            {filteredPayments.map((pay) => (
              <tr key={pay.payment_id}>
                <td style={tdStyle}>{pay.order_id}</td>
                <td style={tdStyle}>{pay.customer_name}</td>
                <td style={tdStyle}>{pay.customer_email}</td>
                <td style={{ ...tdStyle, fontWeight: "bold", color: "#2563eb" }}>
                  ₹{pay.amount}
                </td>
                <td style={tdStyle}>{pay.payment_id}</td>
                <td style={{ ...tdStyle, color: "green", fontWeight: "600" }}>
                  {pay.status}
                </td>
                <td style={tdStyle}>
                  {new Date(pay.created_at).toLocaleString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

/* =============== INLINE STYLES =============== */

const containerStyle = {
  width: "95%",
  margin: "20px auto",
  fontFamily: "Arial, sans-serif",
};

const titleStyle = {
  fontSize: "22px",
  fontWeight: "700",
  marginBottom: "15px",
};

const searchStyle = {
  padding: "10px",
  width: "60%",
  borderRadius: "6px",
  border: "1px solid #ccc",
  marginBottom: "20px",
};

const loadingStyle = { color: "#2563eb", fontWeight: "600" };
const errorStyle = { color: "#e11d48", fontWeight: "600" };
const noDataStyle = { fontStyle: "italic", color: "#6b7280" };

const tableStyle = {
  width: "100%",
  borderCollapse: "collapse",
  backgroundColor: "#fff",
  boxShadow: "0px 2px 10px rgba(0,0,0,0.1)",
};

const thStyle = {
  padding: "10px",
  backgroundColor: "#111827",
  color: "#fff",
  borderBottom: "3px solid #374151",
  textAlign: "left",
};

const tdStyle = {
  padding: "10px",
  borderBottom: "1px solid #ddd",
};
